  aiVivaQuestions: [
    { id: "nif-viva-1", question: "What is a nested if statement?", answer: "An if statement placed inside another if statement. Inner condition evaluated only if outer is true." },
    { id: "nif-viva-2", question: "When is the inner condition of a nested if evaluated?", answer: "Only when the outer condition is true." },
    { id: "nif-viva-3", question: "What is the dangling else problem?", answer: "When an else matches the nearest if instead of the intended outer if in nested structures without braces." },
    { id: "nif-viva-4", question: "How do you prevent the dangling else problem?", answer: "By always using curly braces to explicitly define block boundaries." },
    { id: "nif-viva-5", question: "What is the maximum recommended nesting depth?", answer: "3 levels. Beyond that, code becomes hard to read and maintain." },
    { id: "nif-viva-6", question: "Can a nested if be placed in an else block?", answer: "Yes. A nested if in an else block is equivalent to an else-if construct." },
    { id: "nif-viva-7", question: "What is the scope of a variable declared in an inner if-block?", answer: "Block scope - only accessible within that inner if-block." },
    { id: "nif-viva-8", question: "How many execution paths exist in a two-level nested if with else?", answer: "4 paths: TT, TF, FT, FF." },
    { id: "nif-viva-9", question: "What is the arrow anti-pattern?", answer: "Deeply nested code that forms a triangular shape due to increasing indentation." },
    { id: "nif-viva-10", question: "What are guard clauses?", answer: "Early return statements that check for invalid/edge cases at the start of a method, reducing nesting depth." },
    { id: "nif-viva-11", question: "What is the difference between nested if and else-if?", answer: "Nested if is hierarchical (inner depends on outer). Else-if is flat (mutually exclusive conditions)." },
    { id: "nif-viva-12", question: "Does indentation affect nested if execution?", answer: "No. Java ignores indentation. It only affects readability." },
    { id: "nif-viva-13", question: "What happens if the outer condition is false?", answer: "The entire outer if-block including all inner conditions is skipped." },
    { id: "nif-viva-14", question: "Can you use logical operators inside nested if?", answer: "Yes. You can combine && and || with nested if for complex conditions." },
    { id: "nif-viva-15", question: "What is short-circuit evaluation in nested if?", answer: "If the outer condition is false, inner conditions are not evaluated." },
    { id: "nif-viva-16", question: "What is cyclomatic complexity?", answer: "A measure of the number of linearly independent paths through code. Each nesting level increases it." },
    { id: "nif-viva-17", question: "What is the Extract Method refactoring?", answer: "Moving deeply nested code into a separate method to reduce apparent nesting depth." },
    { id: "nif-viva-18", question: "Can nested if be used inside loops?", answer: "Yes. Nested if can be placed inside any block including loops." },
    { id: "nif-viva-19", question: "What is the advantage of nested if over multiple separate ifs?", answer: "Nested if skips inner conditions when the outer is false, which is more efficient." },
    { id: "nif-viva-20", question: "When should you NOT use nested if?", answer: "When conditions are independent, when nesting exceeds 3 levels, or when logical operators can simplify." },
    { id: "nif-viva-21", question: "What is the output of: if(true) { if(false) print('A'); else print('B'); }", answer: "B. Outer is true, inner is false, so inner else executes." },
    { id: "nif-viva-22", question: "How do you find the largest of three numbers using nested if?", answer: "if (a > b) { if (a > c) print(a); else print(c); } else { if (b > c) print(b); else print(c); }" },
    { id: "nif-viva-23", question: "What is the leap year logic using nested if?", answer: "if (year%4==0) { if (year%100==0) { if (year%400==0) leap; else not; } else leap; } else not;" },
    { id: "nif-viva-24", question: "Can inner if access variables from outer if?", answer: "Yes. Inner blocks can access variables from outer scopes." },
    { id: "nif-viva-25", question: "Can outer if access variables from inner if?", answer: "No. Variables declared in inner blocks are not visible in outer blocks." },
    { id: "nif-viva-26", question: "What is a menu-driven program?", answer: "A program that uses nested if to display a main menu and sub-menus based on user choices." },
    { id: "nif-viva-27", question: "How does nested if improve efficiency?", answer: "By skipping inner condition evaluations when the outer condition is false." },
    { id: "nif-viva-28", question: "What is the relationship between nesting depth and code complexity?", answer: "Deeper nesting increases complexity, making code harder to read, test, and maintain." },
    { id: "nif-viva-29", question: "Can you have a nested if without an else?", answer: "Yes. The else is optional at every level of nesting." },
    { id: "nif-viva-30", question: "What is the best practice for braces in nested if?", answer: "Always use curly braces even for single statements to prevent dangling else and improve readability." },
  ],

